function quickSort(a) {
  if (a.length <= 1) return a;
  const pivot = a[a.length - 1];
  const left = [], right = [];
  for (let i = 0; i < a.length - 1; i++) {
    (a[i] < pivot ? left : right).push(a[i]);
  }
  return [...quickSort(left), pivot, ...quickSort(right)];
}

