def quick_sort(a, low=0, high=None):
    if high is None:
        high = len(a) - 1
    if low < high:
        pivot = a[high]
        i = low - 1
        for j in range(low, high):
            if a[j] <= pivot:
                i += 1
                a[i], a[j] = a[j], a[i]
        a[i + 1], a[high] = a[high], a[i + 1]
        quick_sort(a, low, i)
        quick_sort(a, i + 2, high)
    return a

